L4_1 = "\227\129\157\227\130\140\227\129\140\227\128\129\228\189\153\232\168\136\227\129\170\227\129\147\227\129\168\227\129\171\233\166\150\227\130\146\231\170\129\227\129\163\232\190\188\227\130\128\227\129\170\227\129\163\227\129\166\232\168\128\227\130\143\227\130\140\227\129\159\227\129\174\227\130\146\231\132\161\232\166\150\227\129\151\227\129\166\n\229\131\149\228\184\128\228\186\186\227\129\167\230\157\165\227\129\161\227\130\131\227\129\163\227\129\159\227\130\147\227\129\160\227\128\130\230\136\187\227\129\163\227\129\159\227\130\137\232\172\157\227\130\137\227\129\170\227\129\132\227\129\168\227\128\130"
