L3_1.m_Talk_TWN = L4_1
L4_1 = "\224\184\173\224\185\139\224\184\173 \224\184\161\224\184\178\224\184\139\224\184\178\224\184\129\224\184\180\224\184\154\224\184\173\224\184\129\224\185\132\224\184\161\224\185\136\224\185\131\224\184\171\224\185\137\224\184\162\224\184\184\224\185\136\224\184\135\224\184\153\224\185\136\224\184\176 \224\185\129\224\184\149\224\185\136\224\184\156\224\184\161\224\184\129\224\185\135\224\184\162\224\184\177\224\184\135\224\184\161\224\184\178\224\184\173\224\184\162\224\184\185\224\185\136\224\184\148\224\184\181 \224\185\128\224\184\148\224\184\181\224\185\139\224\184\162\224\184\167\224\185\128\224\184\136\224\184\173\224\184\129\224\184\177\224\184\153\224\184\173\224\184\181\224\184\129\224\184\151\224\184\181\224\184\132\224\184\135\224\184\149\224\185\137\224\184\173\224\184\135\224\184\130\224\184\173\224\185\130\224\184\151\224\184\169\224\184\171\224\184\153\224\185\136\224\184\173\224\184\162"
L3_1.m_Talk_THA = L4_1
L4_1 = "\195\128, Masaki \196\145\195\163 b\225\186\163o t\195\180i \196\145\225\187\171ng can thi\225\187\135p, nh\198\176ng d\195\185 sao th\195\172 t\195\180i c\197\169ng \196\145\195\163 \196\145\225\186\191n \196\145\195\162y. T\195\180i s\225\186\189 ph\225\186\163i xin l\225\187\151i khi g\225\186\183p l\225\186\161i c\225\186\173u \225\186\165y."
L3_1.m_Talk_VTN = L4_1
L4_1 = "\233\130\163\228\184\170\239\188\140\229\133\182\229\174\158\228\187\150\232\174\169\230\136\145\228\184\141\232\166\129\229\164\154\231\174\161\233\151\178\228\186\139\239\188\140\228\189\134\230\136\145\232\191\152\230\152\175\232\191\135\230\157\165\228\186\134\227\128\130\229\155\158\229\142\187\228\185\139\229\144\142\239\188\140\230\136\145\228\188\154\229\146\140\228\187\150\233\129\147\230\173\137\227\128\130"
